import { useMemo, useState } from 'react';
import { DatePicker, Space, Typography } from 'antd';
import type { Dayjs } from 'dayjs';
import { MetricSummary } from '@/components/MetricSummary';
import { CombinedTrendChart } from '@/components/CombinedTrendChart';
import { PvPagesList } from '@/components/PvPagesList';
import { useFilters } from '@/hooks/useFilters';
import { useFilterStore } from '@/stores/filterStore';
import { fillHourlyStatsRange } from '@/lib/normalizeStats';

/** ms → 分钟，保留 1 位小数 */
function msToMinutes(ms: number) {
  if (!Number.isFinite(ms) || ms <= 0) return 0;
  return Math.round((ms / 60000) * 10) / 10;
}

const BEHAVIOR_SERIES = [
  { name: 'PV', field: 'pv' as const },
  { name: 'UV', field: 'uv' as const },
  { name: '点击次数', field: 'clicks' as const },
  {
    name: '平均停留',
    field: 'avgStay' as const,
    yAxisIndex: 1 as const,
    unit: 'min',
    yAxisName: '时长(min)',
    precision: 1,
    transform: msToMinutes,
  },
];

export function BehaviorDashboard() {
  const { stats, loading, hourlyDate, setHourlyDate } = useFilters();
  const dateRange = useFilterStore((s) => s.dateRange);
  const rangeStart = dateRange[0].startOf('day');
  const rangeEnd = dateRange[1].startOf('day');
  const [pageDay, setPageDay] = useState<Dayjs>(() => rangeEnd);

  const clampedPageDay = useMemo(() => {
    if (pageDay.isBefore(rangeStart, 'day')) return rangeStart;
    if (pageDay.isAfter(rangeEnd, 'day')) return rangeEnd;
    return pageDay;
  }, [pageDay, rangeStart, rangeEnd]);

  const clampedHourlyDay = hourlyDate;

  const behavior = stats?.behavior;
  const daily = stats?.daily || [];

  const dayPages = useMemo(() => {
    const key = clampedPageDay.format('YYYY-MM-DD');
    return (
      stats?.pvPagesByDay?.find((d) => d.date === key) || {
        date: key,
        top: [],
        bottom: [],
      }
    );
  }, [stats?.pvPagesByDay, clampedPageDay]);

  const hourlyOfDay = useMemo(() => {
    const filled = fillHourlyStatsRange(stats?.hourlyStats, clampedHourlyDay);
    return filled.map((point) => ({
      ...point,
      hour: point.hour.slice(11, 16) || point.hour,
    }));
  }, [stats?.hourlyStats, clampedHourlyDay]);

  return (
    <div className="monitor-page">
      <MetricSummary
        loading={loading}
        items={[
          {
            title: '页面访问 (PV)',
            value: behavior?.pv || 0,
            description:
              'Page View：页面浏览次数，用户每次进入或刷新页面计为 1 次访问。',
          },
          {
            title: '独立访客 (UV)',
            value: behavior?.uv || 0,
            description:
              'Unique Visitor：按访客标识去重后的独立访问人数，同一访客多次访问只计 1。',
          },
          {
            title: '总点击次数',
            value: behavior?.totalClicks || 0,
            description:
              '统计周期内页面点击事件累计次数，用于衡量交互活跃程度。',
          },
          {
            title: '平均停留',
            value: msToMinutes(behavior?.avgStay || 0),
            suffix: 'min',
            precision: 1,
            description:
              '用户单次访问的平均停留时长（离开页面前），反映页面粘性与内容吸引力。',
          },
        ]}
      />
      <CombinedTrendChart
        title="行为趋势（按天）"
        data={daily}
        xField="date"
        loading={loading}
        series={BEHAVIOR_SERIES}
      />

      <CombinedTrendChart
        title="行为趋势（按小时）"
        data={hourlyOfDay}
        xField="hour"
        loading={loading}
        series={BEHAVIOR_SERIES}
        extra={
          <DatePicker
            value={clampedHourlyDay}
            allowClear={false}
            disabledDate={(current) => {
              if (!current) return false;
              return (
                current.isBefore(rangeStart, 'day') ||
                current.isAfter(rangeEnd, 'day')
              );
            }}
            onChange={(value) => {
              if (value) setHourlyDate(value);
            }}
          />
        }
      />

      <Space
        align="center"
        style={{ width: '100%', justifyContent: 'space-between', marginBottom: 8 }}
        wrap
      >
        <Typography.Text type="secondary">
          按日页面访问排行（当天有访问的页面；最高 Top 20 / 最低 Bottom 20）
        </Typography.Text>
        <DatePicker
          value={clampedPageDay}
          allowClear={false}
          disabledDate={(current) => {
            if (!current) return false;
            return (
              current.isBefore(rangeStart, 'day') ||
              current.isAfter(rangeEnd, 'day')
            );
          }}
          onChange={(value) => {
            if (value) setPageDay(value.startOf('day'));
          }}
        />
      </Space>

      <PvPagesList
        title="访问量最高页面 Top 20"
        data={dayPages.top}
        loading={loading}
        sort="descend"
      />
      <PvPagesList
        title="访问量最低页面 Bottom 20"
        data={dayPages.bottom}
        loading={loading}
        sort="ascend"
      />
    </div>
  );
}
